import sys,pathlib,re
ROOT=pathlib.Path('/workspace/forge-os')
s=(ROOT/'out-v5.3/terminal.html').read_text()
def rep(old,new,count=1):
    global s
    n=s.count(old)
    if n!=count: sys.exit(f'PATCH FAIL ({n} hits): {old[:90]!r}')
    s=s.replace(old,new)
rep("const APP_VERSION='5.3.1';","const APP_VERSION='5.4.0';")
rep('<script src="mp-bridge.js?v=19"></script>','<script src="mp-bridge.js?v=20"></script>')
# swap the 5.3 module for its 5.4 edit (AoD removed, defense label, DMG list)
v53=(ROOT/'devtools/v53.js').read_text(); core=(ROOT/'devtools/v54core.js').read_text()
rep(v53,core)
rep('.aodbtn.on{color:var(--cyan);border-color:var(--cyan)}\n','')
# 3) heat checkbox +2
rep("mod=pNum(k.startsWith('w_')?'mod':'smod')||0;\n if(t=='hnd')return b+","mod=(pNum(k.startsWith('w_')?'mod':'smod')||0)+heatX();\n if(t=='hnd')return b+")
rep(" if(mod)p.push('MOD '+sg(mod));"," if(mod)p.push('MOD '+sg(mod));if(heatX())p.push('HEAT +2');")
rep("+(pNum('mod')||0)+rofBon(rofEffNow());","+(pNum('mod')||0)+rofBon(rofEffNow())+heatX();")
rep("""oninput="S.pilot.smod=this.value;pilotLive()" onchange="skillNote(this)"></label>""","""oninput="S.pilot.smod=this.value;pilotLive()" onchange="skillNote(this)"></label>${hxBox()}""")
rep("|aoa|aoal|aod|aodl|dft|dfw)$/.test(k)","|aoa|aoal|dft|dfw|hx)$/.test(k)")
# 4) All-Out Defense: remove remaining rule hooks
rep("if((q[0]=='dod'&&aodBon('dod'))||(q[0]=='def'&&aodBon(kindOfK(q[1]))))label+=' (ALL-OUT DEFENSE +2)';if((q[0]=='dod'||q[0]=='def')&&aodNow()==5)label+=' (DOUBLE DEFENSE)'","if(heatX())label+=' (HEAT +2)'")
rep("+sitDef()+heatDodge()+aodBon('dod');","+sitDef()+heatDodge();")
rep("if((t=='dod'&&aodBon('dod'))||(t=='def'&&aodBon(kindOfK(k))))p.push('ALL-OUT DEFENSE +2');","")
rep("if(aodNow()){audioEvent('fail');return reject('[FAIL] ALL-OUT DEFENSE :: no attack this turn; switch All-Out Defense off in PILOTING first.')}","")
# 6) targeter: dropdown under the selected weapon (no TARGETER section)
rep("""if(S.view=='sortie')h+=shHead('TG','--TARGETER'+awTitle(),`<span id=sitsum class=dim>${sitSum()}</span>`)+(shOpen('TG')?tgtBody():'');""","""if(S.view=='sortie'&&!weapons().length)h+='<div class="dim tghint">No weapons in this loadout.</div>';""")
rep("<div class=st>${rowStat(x)}${rollRes(x)}</div></div>`}).join('')","<div class=st>${rowStat(x)}${rollRes(x)}</div></div>${S.view=='sortie'?tgtDrop(i):''}`}).join('')")
# 7) remove the gold selected-component box; REPAIR buttons move into IMPACT RESOLUTION
rep("h+=selCard(t,L);","")
rep("""<button id=dm_apply class=damage-apply onclick=\\"applyDmg()\\" ${calc?'':'disabled'}>[APPLY]</button>""","""<button id=dm_apply class=damage-apply onclick=\\"applyDmg()\\" ${calc?'':'disabled'}>[APPLY]</button>${repBtns(t)}""")
# 8) shield row inherits the tab color theme
rep("'<div class=shieldrow>'","'<div class=shieldrow'+dollTT()+'>'",2)
s=re.sub(r'\.mechmap\[data-tt=(\w+)\]([^{,]*)(?=[,{])',lambda m:f'.mechmap[data-tt={m.group(1)}]{m.group(2)},.shieldrow[data-tt={m.group(1)}]{m.group(2)}',s)
# 9) UNDO left of SAVE STATE (solo and table)
rep('<span class=sorbtns><button title="Compile this sortie state','<span class=sorbtns><button type=button onclick="undoLast()" title="Undo the last change to this unit">[UNDO]</button><button title="Compile this sortie state')
# 11) Frame ID only
rep("id=parts[0]||'';cs=parts.slice(1).join(' / ')||'';","id=fidJoin(...parts);cs='';")
rep("S.id=p.id==='PENDING'?'':p.id;S.cs=p.cs==='PENDING'?'':p.cs;","S.id=fidJoin(p.id,p.cs);S.cs='';")
rep("function idline(){return(S.id||S.cs)?`${S.id||'PENDING'} / ${S.cs||'PENDING'}`:'PENDING'}","function idline(){return fidJoin(S.id,S.cs)||'PENDING'}")
rep("function setid(){const a=$('fid').value.trim(),b=$('fcs').value.trim();const e=(a&&nameOK(a))||(b&&nameOK(b));if(e){say('[FAIL] '+e,'bad')}else{if(a)S.id=a;if(b)S.cs=b;","function setid(){const a=$('fid').value.trim();const e=a&&nameOK(a);if(e){say('[FAIL] '+e,'bad')}else{if(a){S.id=a;S.cs=''}")
rep("""<p>FRAME ID<br><input id=fid maxlength=24 value="${esc(S.id)}"></p><p>FRAME MODEL<br><input id=fcs maxlength=24 value="${esc(S.cs)}"></p><button title="Commit the frame ID and model to this loadout" onclick="setid()">""","""<p>FRAME ID<br><input id=fid maxlength=48 value="${esc(fidJoin(S.id,S.cs))}"></p><button title="Commit the frame ID to this loadout" onclick="setid()">""")
rep("The compiled file is named FRAME-ID_MODEL.txt.","The compiled file is named FRAME-ID.txt.")
rep("if(!S.cs){S.cs='UNKNOWN';defaults.push('FRAME MODEL: UNKNOWN')}const fn=(S.id+'_'+S.cs).replace(/ /g,'_')+'.txt';","const fn=fidJoin(S.id,S.cs).replace(/ /g,'_')+'.txt';")
rep("""<span title="frame: ${esc(S.ch[0])}">${esc(S.cs||S.ch[0])}</span>""","""<span title="frame: ${esc(S.ch[0])}">${esc(fidJoin(S.id,S.cs)||S.ch[0])}</span>""")
rep("const mechName=S.cs||S.ch&&S.ch[0]||'UNBOUND FRAME'","const mechName=fidJoin(S.id,S.cs)||S.ch&&S.ch[0]||'UNBOUND FRAME'")
rep("return(d.id||d.cs)?`${d.id||'--'} / ${d.cs||'--'}`:'SHEET '+(i+1)}","return fidJoin(d.id,d.cs)||'SHEET '+(i+1)}")
# 12) roster toggle in the top bar, left of CORE EMPIRE
rep('<header><span class=hbrand','<header><button id="rosterBtn" class="hros" type="button" hidden onclick="window.mpSeats&&mpSeats()" title="Show or hide the table roster">[USERS]</button><span class=hbrand')
# 13) console filter toggle; flavor lines are tagged at the source
rep('<span class="ctitle" onclick="toggleCon()">// OPERATOR CONSOLE</span></div>','<span class="ctitle" onclick="toggleCon()">// OPERATOR CONSOLE</span><button id="lfBtn" class="lfbtn" type="button" aria-pressed="false" onclick="event.stopPropagation();toggleLF()">[ALL LINES]</button></div>')
rep("async function type(el,html){const d=document.createElement('div');d.dataset.k=logKind(html);","async function type(el,html,fk){const d=document.createElement('div');d.dataset.k=fk||logKind(html);")
rep("for(const s of q){if(typeof s=='string')await type(w,s);else await bar_(w,s[1],s[2])}","for(const s of q){if(typeof s=='string')await type(w,s,'flav');else await bar_(w,s[1],s[2])}")
rep("async function bar_(el,label,cnt){const d=document.createElement('div');el.appendChild(d);","async function bar_(el,label,cnt){const d=document.createElement('div');d.dataset.k='flav';el.appendChild(d);")
# 14) catalogue 2-handed / shoulder tags follow the header text colour (--cyan, theme-aware)
rep("${x.th?'<span class=warn> [TWO-HANDED]</span>':''}","${x.th?'<span class=\"warn ctag\"> [TWO-HANDED]</span>':''}")
rep("${x.sd?'<span class=warn> [SHOULDER]</span>':''}","${x.sd?'<span class=\"warn ctag\"> [SHOULDER]</span>':''}")
rep("${x.th?' <span class=warn>[TWO-HANDED]</span>':''}${x.sd?' <span class=warn>[SHOULDER]</span>':''}","${x.th?' <span class=\"warn ctag\">[TWO-HANDED]</span>':''}${x.sd?' <span class=\"warn ctag\">[SHOULDER]</span>':''}")
# FK: per-sheet owner name (host-set, synced in the sheet data)
rep("'importNotesHidden','hitq'];","'importNotesHidden','hitq','own'];")
# in-app changelog
rep("const CHANGELOG=[\n","const CHANGELOG=[\n{v:'5.4.0',items:['Targeter opens under the selected weapon (RoF, mods, Heat, AoA). Heat +2 checkbox beside SKILL MOD. All-Out Defense removed. The defense button shows only the type.','Each damage shot is listed on the roll line. The selected-component box is gone (REPAIR moved into IMPACT RESOLUTION). UNDO sits left of SAVE STATE.','Frame ID only (old ID / MODEL joined). Tab owners show in full; the host can type a new owner on a tab. The roster toggle is in the top bar. Console filter shows only load-bearing lines.']},\n")
css=(ROOT/'devtools/v54.css').read_text(); js=(ROOT/'devtools/v54.js').read_text()
rep("</style></head>",css+"</style></head>")
k=s.rindex("\n</script>"); s=s[:k]+"\n"+js+s[k:]
(ROOT/'out-v5.4/terminal.html').write_text(s); print('v5.4 terminal patched',len(s))
